import AppKit
import Testing
@testable import FeatureClipboard

/// E31-03: ``ConcealedTypeFilter`` skips a pasteboard item whose types include any of the
/// nspasteboard.org concealed/transient/auto-generated conventions, without ever reading the
/// item's string content (invariant 7 -- skipped items are never logged with their content).
@Suite("ConcealedTypeFilter")
struct ConcealedTypeFilterTests {

    @Test
    func concealedTypeFilter_orgNspasteboardConcealedType_skipped() {
        let types: [NSPasteboard.PasteboardType] = [.string, .init("org.nspasteboard.ConcealedType")]

        #expect(ConcealedTypeFilter.shouldSkip(types: types))
    }

    @Test
    func concealedTypeFilter_orgNspasteboardTransientType_skipped() {
        let types: [NSPasteboard.PasteboardType] = [.string, .init("org.nspasteboard.TransientType")]

        #expect(ConcealedTypeFilter.shouldSkip(types: types))
    }

    @Test
    func concealedTypeFilter_orgNspasteboardAutoGeneratedType_skipped() {
        let types: [NSPasteboard.PasteboardType] = [.string, .init("org.nspasteboard.AutoGeneratedType")]

        #expect(ConcealedTypeFilter.shouldSkip(types: types))
    }

    @Test
    func concealedTypeFilter_plainUtf8TextOnly_passed() {
        let types: [NSPasteboard.PasteboardType] = [.init("public.utf8-plain-text")]

        #expect(!ConcealedTypeFilter.shouldSkip(types: types))
    }
}
